package com.fitconnect.bookingservice;
import lombok.RequiredArgsConstructor; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Component @RequiredArgsConstructor public class BookingScheduler {private final BookingRepository repository;private final ClassClient classes;private final NotificationClient notifications;
 @Scheduled(fixedRate=300000) @Transactional public void expirePayments(){repository.findByStatusAndPaymentDeadlineBefore(Booking.Status.PENDING_PAYMENT,LocalDateTime.now()).forEach(b->{classes.decrement(b.getClassId(),b.getNumberOfSpots());b.setStatus(Booking.Status.CANCELLED);notifications.send(new Contracts.NotificationRequest(b.getUserId(),b.getUserEmail(),"BOOKING_CANCELLED","Réservation expirée","Le délai de paiement de "+b.getBookingReference()+" est expiré"));});}
 @Scheduled(fixedRate=300000) @Transactional public void sendReminders(){LocalDateTime target=LocalDateTime.now().plusHours(24);repository.findByStatusAndClassDateBetweenAndReminderSentFalse(Booking.Status.CONFIRMED,target.minusMinutes(3),target.plusMinutes(3)).forEach(b->{notifications.send(new Contracts.NotificationRequest(b.getUserId(),b.getUserEmail(),"BOOKING_REMINDER","Rappel de cours","Votre cours "+b.getClassName()+" commence dans 24 heures"));b.setReminderSent(true);});}
}
